EOF

cat > types.ts << 'EOF'
export enum AppMode { SETUP = 'SETUP', CHAT = 'CHAT', REPORT = 'REPORT' }
export enum SocraticMode { TUTOR = 'TUTOR', CRITIC = 'CRITIC' }
export interface Message { id: string; role: 'user' | 'model'; text: string; timestamp: number; }
export interface SessionConfig { studentName: string; topic: string; mode: SocraticMode; }
export interface AnalysisData {
  summary: string;
  reasoningScore: number; clarityScore: number; skepticismScore: number; processScore: number; reflectionScore: number;
  keyStrengths: string[]; weaknesses: string[];
  transcript: Message[]; aiDeclaration: string;
}
EOF

cat > App.tsx << 'EOF'
import React, { useState } from 'react';
import { AppMode, SessionConfig, Message } from './types';
import SetupView from './components/SetupView';
import ChatView from './components/ChatView';
import ReportView from './components/ReportView';
import { Chat } from "@google/genai";
import { createChatSession } from './services/gemini';

const App: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>(AppMode.SETUP);
  const [config, setConfig] = useState<SessionConfig | null>(null);
  const [chatInstance, setChatInstance] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [aiDeclaration, setAiDeclaration] = useState<string>('');

  const handleStartSession = (newConfig: SessionConfig) => {
    setConfig(newConfig);
    const chat = createChatSession(newConfig.mode, newConfig.topic);
    setChatInstance(chat);
    setAppMode(AppMode.CHAT);
  };

  const handleFinishSession = (declaration: string) => {
    setAiDeclaration(declaration);
    setAppMode(AppMode.REPORT);
  };

  const handleRestart = () => {
    setConfig(null); setChatInstance(null); setMessages([]); setAiDeclaration(''); setAppMode(AppMode.SETUP);
  };

  return (
    <div className="flex flex-col h-full w-full">
      <div className="flex-1 overflow-hidden relative">
        {appMode === AppMode.SETUP && <SetupView onStart={handleStartSession} />}
        {appMode === AppMode.CHAT && config && <ChatView chatInstance={chatInstance} config={config} messages={messages} setMessages={setMessages} onFinish={handleFinishSession} />}
        {appMode === AppMode.REPORT && config && <ReportView config={config} transcript={messages} aiDeclaration={aiDeclaration} onRestart={handleRestart} />}
      </div>
      <footer className="shrink-0 py-1 text-center text-[10px] text-slate-400 bg-slate-50 border-t border-slate-100">Rochane Kherbouche en CC BY SA</footer>
    </div>
  );
};
export default App;
EOF

# Création des composants principaux (Versions simplifiées pour initialisation)
# Nous devrons copier le contenu complet des fichiers composants si le script ci-dessus est trop long, 
# mais ceci créera la structure de base pour que Git fonctionne.

cat > services/gemini.ts << 'EOF'
import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = 'gemini-2.5-flash';

export const createChatSession = (mode: SocraticMode, topic: string): Chat => {
  let systemInstruction = "";
  const tone = "Tu dois impérativement TUTOYER l'étudiant·e.";

  if (mode === SocraticMode.TUTOR) {
    systemInstruction = `Rôle: Tuteur Socratique. Sujet: ${topic}. ${tone} Ne donne jamais la réponse. Questionne le processus.`;
  } else {
    systemInstruction = `Rôle: IA faillible pour critique. Sujet: ${topic}. ${tone} Fais des erreurs subtiles pour tester la vigilance.`;
  }
  return ai.chats.create({ model: MODEL_NAME, config: { systemInstruction } });
};

export const sendMessage = async (chat: Chat, message: string): Promise<string> => {
  try {
    const response = await chat.sendMessage({ message });
    return response.text || "Erreur.";
  } catch (error) { return "Erreur de communication."; }
};

export const generateAnalysis = async (transcript: Message[], topic: string, aiDeclaration: string): Promise<AnalysisData> => {
  const prompt = `Analyse cette session (Sujet: ${topic}). Déclaration: ${aiDeclaration}. Transcript: ${JSON.stringify(transcript)}. Retourne un JSON avec scores et analyse.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            reasoningScore: { type: Type.INTEGER },
            clarityScore: { type: Type.INTEGER },
            skepticismScore: { type: Type.INTEGER },
            processScore: { type: Type.INTEGER },
            reflectionScore: { type: Type.INTEGER },
            keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return { summary: "Erreur", reasoningScore: 0, clarityScore: 0, skepticismScore: 0, processScore: 0, reflectionScore: 0, keyStrengths: [], weaknesses: [], transcript, aiDeclaration };
  }
};
EOF

# Création des fichiers composants vides pour l'instant (à remplir ensuite ou via Git)
touch components/SetupView.tsx components/ChatView.tsx components/ReportView.tsx components/GuideModal.tsx

# Création du fichier .gitignore
cat > .gitignore << 'EOF'
node_modules
dist
.env
.DS_Store
EOF

echo "Installation terminée ! Dossier créé."
```

Une fois que vous avez collé cela et appuyé sur Entrée :

1.  Tapez `ls` : Vous devriez voir le dossier `des-socratic-dialogue` (en bleu).
2.  Tapez `cd des-socratic-dialogue` pour entrer dedans.
3.  Tapez `git init` pour préparer Git.

Dites-moi quand vous avez fait le `git init` !

