import React, { useState, useEffect, useRef } from 'react';
import { Send, StopCircle, RefreshCw, FileSignature, AlertCircle, HelpCircle } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { Chat } from "@google/genai";
import { Message, SessionConfig } from '../types';
import { sendMessage } from '../services/gemini';
import { GuideModal } from './GuideModal';

interface ChatViewProps {
  chatInstance: Chat | null;
  config: SessionConfig;
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  onFinish: (aiDeclaration: string) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ chatInstance, config, messages, setMessages, onFinish }) => {
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showDeclarationModal, setShowDeclarationModal] = useState(false);
  const [showGuide, setShowGuide] = useState(false);
  const [declarationText, setDeclarationText] = useState('');

  // Chronométrie : on suit le timestamp de la dernière activité IA
  const [lastActivityAt, setLastActivityAt] = useState<number>(Date.now());

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const initChat = async () => {
      if (messages.length === 0 && chatInstance) {
        setIsLoading(true);
        try {
          const res = await sendMessage(chatInstance, "Démarre la session selon le protocole pédagogique strict en me tutoyant.");
          const aiMsg: Message = {
            id: crypto.randomUUID(),
            role: 'model',
            text: res.text,
            timestamp: Date.now()
          };
          setMessages([aiMsg]);
          setLastActivityAt(Date.now()); // Début du chrono pour l'étudiant
        } catch (e) { console.error(e); } finally { setIsLoading(false); }
      } else if (messages.length > 0) {
        setLastActivityAt(Date.now());
      }
    };
    initChat();
  }, [chatInstance]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!inputText.trim() || !chatInstance || isLoading) return;

    const now = Date.now();
    const reflectionTime = now - lastActivityAt; // Véritable temps de réflexion

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: inputText,
      timestamp: now,
      responseTimeMs: reflectionTime // On attache le temps de réflexion au message utilisateur
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);

    try {
      const res = await sendMessage(chatInstance, userMsg.text);
      const aiMsg: Message = {
        id: crypto.randomUUID(),
        role: 'model',
        text: res.text,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, aiMsg]);
      setLastActivityAt(Date.now()); // Reset du chrono pour le prochain tour
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      {showGuide && <GuideModal onClose={() => setShowGuide(false)} />}

      {showDeclarationModal && (
        <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full p-8 animate-in fade-in zoom-in duration-300">
            <h2 className="text-2xl font-bold flex items-center gap-3 mb-6"><FileSignature className="text-indigo-600" /> Journal de bord IA</h2>
            <div className="bg-indigo-50 p-4 mb-6 text-sm text-indigo-900 rounded-lg">
              Décris ici ta méthodologie : as-tu utilisé des outils externes ? Quel a été ton prompt principal ? Cette déclaration sera comparée à ton comportement réel par Argos.
            </div>
            <textarea value={declarationText} onChange={(e) => setDeclarationText(e.target.value)} placeholder="Usage de l'IA..." className="w-full h-40 p-4 border rounded-xl mb-6" />
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowDeclarationModal(false)} className="px-5 py-2 text-slate-600">Annuler</button>
              <button onClick={() => onFinish(declarationText || "Non déclarée.")} className="px-6 py-2 bg-indigo-600 text-white rounded-lg font-bold">Générer l'Audit Final</button>
            </div>
          </div>
        </div>
      )}

      <header className="bg-white border-b px-6 py-4 flex justify-between items-center shadow-sm z-10">
        <div>
          <h2 className="text-lg font-bold text-slate-800">{config.topic}</h2>
          <p className="text-[10px] text-slate-500 uppercase font-bold">{config.studentName} | {config.domain} | {config.mode}</p>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowGuide(true)} className="p-2 text-slate-400 hover:text-indigo-600"><HelpCircle size={20} /></button>
          <button onClick={() => setShowDeclarationModal(true)} className="flex items-center gap-2 px-4 py-2 bg-rose-600 text-white rounded-lg text-sm font-bold shadow-md"><StopCircle size={16} /> TERMINER</button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 scrollbar-hide">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl px-5 py-4 shadow-sm ${msg.role === 'user' ? 'bg-slate-800 text-white rounded-br-none' : 'bg-white text-slate-800 border rounded-bl-none'}`}>
              <div className="prose prose-sm max-w-none prose-slate"><ReactMarkdown>{msg.text}</ReactMarkdown></div>
              <div className="text-[9px] mt-2 opacity-60 uppercase font-bold tracking-widest">{msg.role === 'model' ? 'ARGOS AGENT' : config.studentName}</div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white border rounded-2xl px-5 py-4 flex items-center gap-2">
              <RefreshCw className="animate-spin text-slate-400" size={16} /><span className="text-xs text-slate-500 font-bold uppercase">Analyse en cours...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="bg-white border-t p-4 sm:p-6">
        <div className="max-w-4xl mx-auto relative">
          <textarea ref={textareaRef} value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={handleKeyPress} placeholder="Écris ici ton raisonnement..." className="w-full bg-slate-50 rounded-xl px-4 py-3 border focus:ring-2 focus:ring-indigo-500 min-h-[56px] resize-none" rows={1} />
          <button onClick={handleSend} disabled={!inputText.trim() || isLoading} className="absolute right-2 bottom-2 p-2 bg-slate-900 text-white rounded-lg disabled:opacity-50"><Send size={18} /></button>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Chat, Type, Content } from "@google/genai";
import { Message, SocraticMode, AnalysisData, DomainType } from "../types";
import { DOMAIN_CRITERIA } from "../domainCriteria";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-pro-preview";
const CHAT_TEMPERATURE = 0.7;
const ANALYSIS_TEMPERATURE = 0.3;
const TUTOR_NAME = "ARGOS";

const getThinkingBudget = (domain: DomainType, isAnalysis: boolean): number => {
  const base = isAnalysis ? 2 : 1;
  if (domain === DomainType.SCIENTIFIC_TECHNICAL) return 3072 * base;
  if (domain === DomainType.DEBATE_THESIS) return 2048 * base;
  return 1024 * base;
};

export const createChatSession = (mode: SocraticMode, topic: string, history: Message[] = [], domain: DomainType = DomainType.DEBATE_THESIS): Chat => {
  const criteria = DOMAIN_CRITERIA[domain];
  const systemInstruction = `
IDENTITÉ : Tu es ${TUTOR_NAME}, agent du Dialogue Évaluatif Socratique. Sujet : "${topic}". Domaine : "${criteria.label}".

RÉFÉRENTIEL DISCIPLINAIRE (CRITÈRES À ÉPROUVER) :
${criteria.criteria.map(c => `- ${c.label} (Niveaux attendus : ${c.levels[10]} ou ${c.levels[20]})`).join("\n")}

TON : Tutoiement, sobre, sceptique. Jamais de compliments.

MODE : ${mode === SocraticMode.TUTOR ? 'DÉFENSE (pousser l\'élève à justifier)' : 'AUDIT (proposer un texte à corriger)'}.

CONTRÔLE : Une seule question par message. Longueur 70-140 mots. Trace obligatoire (Phases 2+) sur 2 lignes : "Exigence:" et "Contrôle:".
  `.trim();

  return ai.chats.create({
    model: MODEL_NAME,
    history: history.map(m => ({ role: m.role, parts: [{ text: m.text }] })),
    config: { systemInstruction, temperature: CHAT_TEMPERATURE, thinkingConfig: { thinkingBudget: getThinkingBudget(domain, false) } }
  });
};

export const sendMessage = async (chat: Chat, message: string) => {
  try {
    const response = await chat.sendMessage({ message });
    return { text: response.text || "Erreur." };
  } catch (e) {
    return { text: "Erreur technique." };
  }
};

export const generateAnalysis = async (
  transcript: Message[],
  topic: string,
  aiDeclaration: string,
  domain: DomainType = DomainType.DEBATE_THESIS
): Promise<AnalysisData> => {
  const criteria = DOMAIN_CRITERIA[domain];
  const transcriptText = transcript.map(m => {
    const time = m.responseTimeMs ? ` [Réflexion: ${Math.round(m.responseTimeMs / 1000)}s]` : "";
    return `[${m.role === "user" ? "Étudiant" : TUTOR_NAME}]${time}: ${m.text}`;
  }).join("\n");

  const prompt = `
Analyse ce Dialogue Évaluatif Socratique sur "${topic}".

GRILLE DISCIPLINAIRE DE RÉFÉRENCE (Score sur 100) :
Pour chaque critère, attribue 0, 10 ou 20 points selon les paliers suivants :
${criteria.criteria.map(c => `- ${c.label} :
    - 0 pt : ${c.levels[0]}
    - 10 pts : ${c.levels[10]}
    - 20 pts : ${c.levels[20]}`).join("\n")}

DÉCLARATION IA : "${aiDeclaration}"

TRANSCRIPTION :
${transcriptText}

TA MISSION :
1. "disciplinaryDiscernmentScore" : Somme des points (0, 10 ou 20) pour les 5 critères ci-dessus. Justifie chaque point par un indice précis.
2. "aiDeclarationCoherenceScore" : Évalue si l'élève a utilisé l'IA sans le dire. Indice : réponses complexes en moins de 5 secondes, style trop policé, structure GPT.
3. Synthèse (summary) : 180 mots valorisant le processus.

SORTIE JSON :
{
  "summary": string,
  "reasoningScore": int,
  "clarityScore": int,
  "skepticismScore": int,
  "processScore": int,
  "reflectionScore": int,
  "disciplinaryDiscernmentScore": int,
  "aiDeclarationCoherenceScore": int,
  "keyStrengths": string[],
  "weaknesses": string[],
  "aiUsageAnalysis": string
}
  `.trim();

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        temperature: ANALYSIS_TEMPERATURE,
        thinkingConfig: { thinkingBudget: getThinkingBudget(domain, true) },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            reasoningScore: { type: Type.INTEGER },
            clarityScore: { type: Type.INTEGER },
            skepticismScore: { type: Type.INTEGER },
            processScore: { type: Type.INTEGER },
            reflectionScore: { type: Type.INTEGER },
            disciplinaryDiscernmentScore: { type: Type.INTEGER },
            aiDeclarationCoherenceScore: { type: Type.INTEGER },
            keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
            aiUsageAnalysis: { type: Type.STRING }
          },
          required: ["summary", "disciplinaryDiscernmentScore", "aiDeclarationCoherenceScore", "keyStrengths", "weaknesses", "aiUsageAnalysis"]
        }
      }
    });

    return { ...JSON.parse(response.text), transcript, aiDeclaration };
  } catch (e) {
    console.error(e);
    return { summary: "Erreur analyse.", reasoningScore: 0, clarityScore: 0, skepticismScore: 0, processScore: 0, reflectionScore: 0, disciplinaryDiscernmentScore: 0, aiDeclarationCoherenceScore: 0, keyStrengths: [], weaknesses: [], aiUsageAnalysis: "Erreur.", transcript, aiDeclaration };
  }
};

