import React, { useState } from 'react';
import { AppMode, SessionConfig, Message } from './types';
import { SetupView } from './components/SetupView';
import { ChatView } from './components/ChatView';
import { ReportView } from './components/ReportView';
import { LoginView } from './components/LoginView';
import { Chat } from "@google/genai";
import { createChatSession } from './services/gemini';

const App: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>(AppMode.LOGIN);
  const [config, setConfig] = useState<SessionConfig | null>(null);
  const [chatInstance, setChatInstance] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [aiDeclaration, setAiDeclaration] = useState<string>('');

  const handleLoginSuccess = () => {
    setAppMode(AppMode.SETUP);
  };

  const handleStartSession = (newConfig: SessionConfig) => {
    setConfig(newConfig);
    setMessages([]); // Reset messages for new session

    // Initialisation avec le domaine correct
    const chat = createChatSession(newConfig.mode, newConfig.topic, [], newConfig.domain);
    setChatInstance(chat);

    setAppMode(AppMode.CHAT);
  };

  const handleResumeSession = (restoredConfig: SessionConfig, restoredMessages: Message[], restoredDeclaration: string) => {
    setConfig(restoredConfig);
    setMessages(restoredMessages);
    setAiDeclaration(restoredDeclaration);

    const chat = createChatSession(restoredConfig.mode, restoredConfig.topic, restoredMessages, restoredConfig.domain);
    setChatInstance(chat);

    setAppMode(AppMode.CHAT);
  };

  const handleFinishSession = (declaration: string) => {
    setAiDeclaration(declaration);
    setAppMode(AppMode.REPORT);
  };

  const handleRestart = () => {
    setConfig(null);
    setChatInstance(null);
    setMessages([]);
    setAiDeclaration('');
    setAppMode(AppMode.SETUP);
  };

  return (
    <div className="flex flex-col h-full w-full">
      <div className="flex-1 overflow-hidden relative">
        {appMode === AppMode.LOGIN && (
          <LoginView onSuccess={handleLoginSuccess} />
        )}

        {appMode === AppMode.SETUP && (
          <SetupView 
            onStart={handleStartSession} 
            onResume={handleResumeSession} 
          />
        )}

        {appMode === AppMode.CHAT && config && (
          <ChatView 
            chatInstance={chatInstance}
            config={config} 
            messages={messages}
            setMessages={setMessages}
            onFinish={handleFinishSession}
          />
        )}

        {appMode === AppMode.REPORT && config && (
          <ReportView 
            config={config} 
            transcript={messages} 
            aiDeclaration={aiDeclaration}
            onRestart={handleRestart}
          />
        )}
      </div>
      {appMode !== AppMode.LOGIN && (
        <footer className="shrink-0 py-1 text-center text-[10px] text-slate-400 bg-slate-50 border-t border-slate-100">
          Rochane Kherbouche en CC BY SA
        </footer>
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData, DomainType } from "../types";
import { DOMAIN_CRITERIA } from "../domainCriteria";

// Initialisation sécurisée
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const CHAT_MODEL = "gemini-3-flash-preview";
const ANALYSIS_MODEL = "gemini-3-pro-preview";
const TUTOR_NAME = "ARGOS";

export const createChatSession = (mode: SocraticMode, topic: string, history: Message[] = [], domain: DomainType = DomainType.DEBATE_THESIS): Chat => {
  const domainInfo = DOMAIN_CRITERIA[domain] || DOMAIN_CRITERIA[DomainType.DEBATE_THESIS];
  const ai = getAI();

  const systemInstruction = `
Tu es ${TUTOR_NAME}, un tuteur socratique expert en pensée critique. Sujet : "${topic}". Domaine : "${domainInfo.label}".

OBJECTIF : Évaluer la capacité de l'étudiant à raisonner par lui-même.
CRITÈRES DISCIPLINAIRES : ${domainInfo.criteria.join(", ")}.

MÉTHODE :
- Tutoiement systématique. Style sobre, direct, légèrement sceptique.
- Ne donne JAMAIS la réponse.
- Pose une seule question à la fois, courte et percutante.
- Mode ${mode === SocraticMode.TUTOR ? 'DÉFENSE : l\'étudiant défend une thèse' : 'CRITIQUE : l\'étudiant doit trouver les failles d\'un texte que tu lui proposes'}.

STRUCTURE : À partir de la phase 2, ajoute systématiquement en fin de message :
Exigence : [ce qu'on attend de l'étudiant maintenant]
Contrôle : [la règle logique à ne pas briser]
  `.trim();

  return ai.chats.create({
    model: CHAT_MODEL,
    history: history.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    })),
    config: { 
      systemInstruction, 
      temperature: 0.7 
    }
  });
};

export const sendMessage = async (chat: Chat, message: string) => {
  try {
    if (!chat) throw new Error("Chat session not initialized");
    const response = await chat.sendMessage({ message });
    const text = response.text;

    if (!text || text.trim() === "") {
      return { text: "Argos réfléchit... (Désolé, la réponse est vide. Peux-tu reformuler ?)" };
    }

    return { text };
  } catch (e: any) {
    console.error("Gemini Error:", e);
    const errorMsg = e.message?.includes("API_KEY") 
      ? "Clé API non configurée." 
      : "Erreur de connexion avec l'agent Argos. Vérifie ta connexion ou réessaie.";
    return { text: errorMsg };
  }
};

export const generateAnalysis = async (
  transcript: Message[],
  topic: string,
  aiDeclaration: string,
  domain: DomainType = DomainType.DEBATE_THESIS
): Promise<AnalysisData> => {
  const domainInfo = DOMAIN_CRITERIA[domain] || DOMAIN_CRITERIA[DomainType.DEBATE_THESIS];
  const ai = getAI();
  const transcriptText = transcript.map(m => `[${m.role === "user" ? "Étudiant" : TUTOR_NAME}]: ${m.text}`).join("\n");

  const prompt = `
Analyse ce dialogue socratique sur "${topic}" (Domaine: ${domainInfo.label}).
L'étudiant déclare ceci sur son usage de l'IA : "${aiDeclaration}"

Transcription :
${transcriptText}

Évalue sur 100 :
1. "disciplinaryDiscernmentScore" : Maîtrise des critères : ${domainInfo.criteria.join(", ")}.
2. "aiDeclarationCoherenceScore" : Sincérité de l'étudiant (vitesse de réponse, style).

Réponds au format JSON strict.
  `.trim();

  try {
    const response = await ai.models.generateContent({
      model: ANALYSIS_MODEL,
      contents: prompt,
      config: {
        temperature: 0.2,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            reasoningScore: { type: Type.INTEGER },
            clarityScore: { type: Type.INTEGER },
            skepticismScore: { type: Type.INTEGER },
            processScore: { type: Type.INTEGER },
            reflectionScore: { type: Type.INTEGER },
            disciplinaryDiscernmentScore: { type: Type.INTEGER },
            aiDeclarationCoherenceScore: { type: Type.INTEGER },
            keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
            aiUsageAnalysis: { type: Type.STRING }
          },
          required: ["summary", "disciplinaryDiscernmentScore", "aiDeclarationCoherenceScore", "keyStrengths", "weaknesses", "aiUsageAnalysis"]
        }
      }
    });

    return { ...JSON.parse(response.text), transcript, aiDeclaration };
  } catch (e) {
    console.error("Analysis Error:", e);
    return { 
      summary: "Échec de l'analyse automatique.", 
      reasoningScore: 50, clarityScore: 50, skepticismScore: 50, processScore: 50, reflectionScore: 50, 
      disciplinaryDiscernmentScore: 0, aiDeclarationCoherenceScore: 0, 
      keyStrengths: [], weaknesses: [], aiUsageAnalysis: "L'analyse n'a pas pu être générée.", 
      transcript, aiDeclaration 
    };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Send, StopCircle, RefreshCw, FileSignature, HelpCircle, AlertCircle } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { Chat } from "@google/genai";
import { Message, SessionConfig } from '../types';
import { sendMessage } from '../services/gemini';
import { GuideModal } from './GuideModal';

interface ChatViewProps {
  chatInstance: Chat | null;
  config: SessionConfig;
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  onFinish: (aiDeclaration: string) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ chatInstance, config, messages, setMessages, onFinish }) => {
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showDeclarationModal, setShowDeclarationModal] = useState(false);
  const [showGuide, setShowGuide] = useState(false);
  const [declarationText, setDeclarationText] = useState('');
  const [lastActivityAt, setLastActivityAt] = useState<number>(Date.now());
  const [error, setError] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const isStarted = useRef(false);

  useEffect(() => {
    if (isStarted.current || !chatInstance) return;

    const initChat = async () => {
      // On ne lance l'init que si on n'a pas encore de messages
      if (messages.length === 0) {
        setIsLoading(true);
        setError(null);
        try {
          const res = await sendMessage(chatInstance, "Bonjour Argos, je suis prêt. Démarre la session en me tutoyant.");
          const aiMsg: Message = {
            id: crypto.randomUUID(),
            role: 'model',
            text: res.text || "Bonjour ! Je suis prêt pour notre échange. De quoi souhaites-tu discuter précisément ?",
            timestamp: Date.now()
          };
          setMessages([aiMsg]);
          setLastActivityAt(Date.now());
          isStarted.current = true;
        } catch (e) { 
          console.error("Init error:", e);
          setError("Impossible de démarrer la session avec Argos.");
        } finally { 
          setIsLoading(false); 
        }
      } else {
        isStarted.current = true;
        setLastActivityAt(Date.now());
      }
    };
    initChat();
  }, [chatInstance, messages.length, setMessages]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!inputText.trim() || !chatInstance || isLoading) return;

    setError(null);
    const now = Date.now();
    const reflectionTime = now - lastActivityAt;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: inputText,
      timestamp: now,
      responseTimeMs: reflectionTime
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);

    try {
      const res = await sendMessage(chatInstance, userMsg.text);
      const aiMsg: Message = {
        id: crypto.randomUUID(),
        role: 'model',
        text: res.text,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, aiMsg]);
      setLastActivityAt(Date.now());
    } catch (error) {
      console.error(error);
      setError("Le message n'a pas pu être envoyé.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      {showGuide && <GuideModal onClose={() => setShowGuide(false)} />}

      {showDeclarationModal && (
        <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full p-8 animate-in fade-in zoom-in duration-300">
            <h2 className="text-2xl font-bold flex items-center gap-3 mb-6"><FileSignature className="text-indigo-600" /> Journal de bord IA</h2>
            <div className="bg-indigo-50 p-4 mb-6 text-sm text-indigo-900 rounded-lg">
              Décris ici ta méthodologie : as-tu utilisé des outils externes ? Quel a été ton prompt principal ?
            </div>
            <textarea value={declarationText} onChange={(e) => setDeclarationText(e.target.value)} placeholder="Usage de l'IA..." className="w-full h-40 p-4 border rounded-xl mb-6 focus:ring-2 focus:ring-indigo-500 outline-none" />
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowDeclarationModal(false)} className="px-5 py-2 text-slate-600">Annuler</button>
              <button onClick={() => onFinish(declarationText || "Non déclarée.")} className="px-6 py-2 bg-indigo-600 text-white rounded-lg font-bold">Générer l'Audit Final</button>
            </div>
          </div>
        </div>
      )}

      <header className="bg-white border-b px-6 py-4 flex justify-between items-center shadow-sm z-10">
        <div>
          <h2 className="text-lg font-bold text-slate-800">{config.topic}</h2>
          <p className="text-[10px] text-slate-500 uppercase font-bold tracking-wider">{config.studentName} | {config.domain} | {config.mode}</p>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowGuide(true)} className="p-2 text-slate-400 hover:text-indigo-600 transition-colors"><HelpCircle size={20} /></button>
          <button onClick={() => setShowDeclarationModal(true)} className="flex items-center gap-2 px-4 py-2 bg-rose-600 text-white rounded-lg text-sm font-bold shadow-md hover:bg-rose-700 transition-all active:scale-95"><StopCircle size={16} /> TERMINER</button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6 scrollbar-hide">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl px-5 py-4 shadow-sm border ${msg.role === 'user' ? 'bg-slate-800 text-white border-slate-700 rounded-br-none' : 'bg-white text-slate-800 border-slate-200 rounded-bl-none'}`}>
              <div className={`prose prose-sm max-w-none ${msg.role === 'user' ? 'prose-invert' : 'prose-slate'}`}>
                <ReactMarkdown>{(msg.text && msg.text.trim()) || "..."}</ReactMarkdown>
              </div>
              <div className="text-[9px] mt-2 opacity-60 uppercase font-bold tracking-widest border-t border-current/10 pt-1">
                {msg.role === 'model' ? 'ARGOS AGENT' : config.studentName}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white border border-slate-200 rounded-2xl px-5 py-4 flex items-center gap-3 shadow-sm">
              <RefreshCw className="animate-spin text-indigo-500" size={16} />
              <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Analyse de ton raisonnement...</span>
            </div>
          </div>
        )}

        {error && (
          <div className="mx-auto max-w-md bg-rose-50 border border-rose-200 text-rose-800 px-4 py-3 rounded-xl flex items-center gap-3">
            <AlertCircle size={20} className="shrink-0" />
            <p className="text-xs font-medium">{error}</p>
            <button onClick={() => window.location.reload()} className="text-[10px] font-bold uppercase underline">Actualiser</button>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="bg-white border-t p-4 sm:p-6">
        <div className="max-w-4xl mx-auto relative">
          <textarea 
            value={inputText} 
            onChange={(e) => setInputText(e.target.value)} 
            onKeyDown={handleKeyPress} 
            placeholder="Réponds ici..." 
            disabled={isLoading}
            className="w-full bg-slate-50 rounded-xl pl-4 pr-12 py-3 border border-slate-200 focus:ring-2 focus:ring-indigo-500 focus:bg-white min-h-[56px] resize-none outline-none transition-all disabled:opacity-50" 
            rows={Math.min(5, inputText.split('\n').length || 1)} 
          />
          <button 
            onClick={handleSend} 
            disabled={!inputText.trim() || isLoading} 
            className="absolute right-2 bottom-2 p-2 bg-slate-900 text-white rounded-lg disabled:opacity-50 hover:bg-slate-800 transition-all active:scale-90"
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </div>
  );
};

